  CONSTRAINT `fk_fa_planned_activity_errand_id` FOREIGN KEY (`errand_id`) REFERENCES `errand_financial_assistance` (`errand_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `errand_fa_planning` (
  `errand_id` varchar(36) NOT NULL,
  `person` varchar(255) DEFAULT NULL,
  `planning_type` varchar(64) DEFAULT NULL,
  `work_extent` varchar(32) DEFAULT NULL,
  `work_description` longtext DEFAULT NULL,
  `sick_leave_level` varchar(32) DEFAULT NULL,
  `sfi_study_path` varchar(64) DEFAULT NULL,
  `sfi_course` varchar(64) DEFAULT NULL,
  `other_description` longtext DEFAULT NULL,
  KEY `idx_fa_planning_errand_id` (`errand_id`),
  CONSTRAINT `fk_fa_planning_errand_id` FOREIGN KEY (`errand_id`) REFERENCES `errand_financial_assistance` (`errand_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `errand_financial_assistance` (
  `errand_id` varchar(36) NOT NULL,
  `application_type` varchar(32) DEFAULT NULL,
  `marital_status` varchar(32) DEFAULT NULL,
  `period_month` int(11) DEFAULT NULL,
  `period_year` int(11) DEFAULT NULL,
  `period_choice` varchar(32) DEFAULT NULL,
  `other_benefit_description` longtext DEFAULT NULL,
  `livelihood_description` longtext DEFAULT NULL,
  `has_children_under21` bit(1) DEFAULT NULL,
  `children_residence_changed` bit(1) DEFAULT NULL,
  `children_residence_change_description` longtext DEFAULT NULL,
  `housing_form` varchar(32) DEFAULT NULL,
  `housing_rooms_plus_kitchen` int(11) DEFAULT NULL,
  `housing_description` longtext DEFAULT NULL,
  `housing_changed` bit(1) DEFAULT NULL,
  `housing_change_description` longtext DEFAULT NULL,
  `has_incomes` bit(1) DEFAULT NULL,
  `has_pending_benefits` bit(1) DEFAULT NULL,
  `has_assets` bit(1) DEFAULT NULL,
  `stays_in_municipality` bit(1) DEFAULT NULL,
  `stay_description` longtext DEFAULT NULL,
  `attestation` bit(1) DEFAULT NULL,
  `attested_at` datetime(6) DEFAULT NULL,
  `created` datetime(6) DEFAULT NULL,
  `modified` datetime(6) DEFAULT NULL,
  `housing_person_count` int(11) DEFAULT NULL,
  `last_daily_run_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`errand_id`),
  CONSTRAINT `fk_financial_assistance_errand_id` FOREIGN KEY (`errand_id`) REFERENCES `errand` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `errand_financial_assistance_calculation_draft` (
  `errand_id` varchar(36) NOT NULL,
  `application_month` varchar(7) DEFAULT NULL,
  `created` datetime(6) DEFAULT NULL,
  `updated` datetime(6) DEFAULT NULL,
  `norm_id` int(11) DEFAULT NULL,
  `calculation_from_date` date DEFAULT NULL,
  `calculation_to_date` date DEFAULT NULL,
  `calculation_date` date DEFAULT NULL,
  `has_custom_household_size` bit(1) DEFAULT NULL,
  `household_size` int(11) DEFAULT NULL,
  PRIMARY KEY (`errand_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE `errand_financial_assistance_monitoring` (
